def get(record,path):
    value=record
    for part in path.split("."):
        if not isinstance(value,dict) or part not in value:return None
        value=value[part]
    return copy.deepcopy(value)

def fact(value,status,sids,notes):
    return {"value":value,"status":status,"source_ids":sids,"notes":notes}

